import { createReadStream } from 'node:fs';
import { writeFile } from 'node:fs/promises';
import readline from 'node:readline';

await writeFile('besar.txt', 'x'.repeat(200000));
let potongan = 0;
for await (const p of createReadStream('besar.txt')) potongan++;
console.log('Potongan:', potongan);

const hitung = {};
const rl = readline.createInterface({ input: createReadStream('akses.log') });
for await (const baris of rl) {
  const status = baris.split(' ')[2];
  hitung[status] = (hitung[status] || 0) + 1;
}
console.log(hitung);

