// === nilai.txt ===
4
5
6
// === main.js ===
import { createReadStream } from 'node:fs';
import readline from 'node:readline';
const rl = readline.createInterface({ input: createReadStream('nilai.txt') });
let jumlah = 0;
for await (const baris of rl) jumlah += Number(baris);
console.log('Jumlah:', jumlah);
